]

def find_rotation(arr, target):
    """Find rotation (0, 90, 180, 270) that maps arr to target, or None"""
    def rot90cw(arr):
        return np.rot90(arr, k=-1)

    for k in range(4):
        rotated = np.rot90(arr, k=-k)  # k=0 = 0°, k=1 = 270°, k=2 = 180°, k=3 = 90° CW
        if np.array_equal(rotated, target):
