import numpy as np

test_input = [
    [6, 1, 0],
    [4, 8, 9],
    [2, 7, 3]
]

in_np = np.array(test_input)

def rot90cw(arr):
    return np.rot90(arr, k=-1)

def rot180(arr):
    return np.rot90(arr, k=-2)

def rot270cw(arr):
    return np.rot90(arr, k=-3)

tl = in_np.copy()
tr = rot90cw(in_np)
bl = rot270cw(in_np)
br = rot180(in_np)

output = np.vstack([
    np.hstack([tl, tr]),
    np.hstack([bl, br])
])

# Format as nested list
result = output.tolist()
print("Final result:")
for row in result:
    print(row)
print("\nJSON format:", result)
